private val Navy=Color(0xFF0B2D4D);private val Blue=Color(0xFF1976D2);private val Green=Color(0xFF2E7D32);private val Orange=Color(0xFFF57C00)
private enum class Tab(val title:String,val icon:ImageVector){TODAY("Ma",Icons.Default.Home),LOG("Napló",Icons.Default.List),EARNING("Kereset",Icons.Default.AttachMoney),STATS("Statisztika",Icons.Default.BarChart),SETTINGS("Beállítások",Icons.Default.Settings)}

@Composable fun RoadRecordApp(vm:MainViewModel=viewModel()){
 var tab by remember{mutableStateOf(Tab.TODAY)};var detailId by remember{mutableStateOf<Long?>(null)};var placesOpen by remember{mutableStateOf(false)}
 val msg by vm.message.collectAsState();LaunchedEffect(msg){if(msg!=null){delay(3500);vm.clearMessage()}}
 MaterialTheme(colorScheme=lightColorScheme(primary=Navy,secondary=Blue,tertiary=Orange)){Scaffold(topBar={TopAppBar(title={Row(verticalAlignment=Alignment.CenterVertically){Logo();Spacer(Modifier.width(10.dp));Text("RoadRecord",fontWeight=FontWeight.Bold)}},colors=TopAppBarDefaults.topAppBarColors(containerColor=Navy,titleContentColor=Color.White))},bottomBar={NavigationBar{Tab.entries.forEach{NavigationBarItem(selected=tab==it,onClick={tab=it;detailId=null;placesOpen=false},icon={Icon(it.icon,null)},label={Text(it.title)})}}},snackbarHost={if(msg!=null)Box(Modifier.fillMaxSize(),contentAlignment=Alignment.BottomCenter){Surface(color=Color(0xFFB3261E),shape=RoundedCornerShape(8.dp),modifier=Modifier.padding(16.dp)){Text(msg!!,color=Color.White,modifier=Modifier.padding(12.dp))}}}){pad->Box(Modifier.padding(pad).fillMaxSize()){when{placesOpen->PlacesScreen(vm,onBack={placesOpen=false});detailId!=null->DayDetail(vm,detailId!!,{detailId=null});else->when(tab){Tab.TODAY->TodayScreen(vm,{detailId=it},{placesOpen=true});Tab.LOG->LogScreen(vm){detailId=it};Tab.EARNING->EarningsScreen(vm);Tab.STATS->StatsScreen(vm);Tab.SETTINGS->SettingsScreen(vm,{placesOpen=true})}}}}}
}
@Composable private fun Logo(){Surface(Modifier.size(36.dp),shape=RoundedCornerShape(10.dp),color=Color.White){Box(contentAlignment=Alignment.Center){Text("RR",color=Navy,fontWeight=FontWeight.Black)}}}
private fun duration(ms:Long)="%02d:%02d".format(ms/3600000,(ms/60000)%60)
private fun money(v:Long)=NumberFormat.getIntegerInstance(Locale("hu","HU")).format(v)+" Ft"
private fun time(v:Long)=java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(v))
@Composable private fun LiveTick():Long{var now by remember{mutableLongStateOf(System.currentTimeMillis())};LaunchedEffect(Unit){while(true){delay(1000);now=System.currentTimeMillis()}};return now}

@Composable private fun TodayScreen(vm:MainViewModel,onDetail:(Long)->Unit,onPlaces:()->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val now=LiveTick();val today=days.firstOrNull{it.day.date==LocalDate.now().toString()};val context=LocalContext.current;val perms=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){}
 fun service(day:Long,start:Boolean){val intent=Intent(context,TrackingService::class.java).setAction(if(start)TrackingService.ACTION_START else TrackingService.ACTION_STOP).putExtra(TrackingService.EXTRA_DAY,day);if(start)context.startForegroundService(intent)else context.startService(intent)}
 LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text(LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy. MMMM d.",Locale("hu"))),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};if(today==null){item{HeroCard("Kezdésre kész","Indítsd el a munkanapot egyetlen gombnyomással.",Green,"Munkakezdés",Icons.Default.PlayArrow){vm.run{val id=vm.repo.startWork();service(id,true)}}}}else{val s=today.summary(settings,now);item{SummaryRow(s)};items(today.events.sortedBy{it.timestamp}){e->EventRow(e){onDetail(today.day.id)}};item{val last=today.events.maxByOrNull{it.timestamp}?.type;when(last){EventType.WORK_END->OutlinedButton(onClick={onDetail(today.day.id)},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.CheckCircle,null);Text("  Munkanap részletei")};EventType.TRIP_START->HeroCard("Úton vagy", "GPS útvonalrögzítés aktív",Orange,"Visszaérkezés",Icons.Default.Flag){vm.run{vm.repo.nextAction(today.day.id)}};else->HeroCard("Következő művelet","Indíts új utat; tetszőleges számú út rögzíthető.",Blue,"Útra indulás",Icons.Default.DirectionsCar){if(ContextCompat.checkSelfPermission(context,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)perms.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.POST_NOTIFICATIONS));vm.run{vm.repo.nextAction(today.day.id);service(today.day.id,true)}}};if(last!=EventType.WORK_END&&last!=EventType.TRIP_START)OutlinedButton(onClick={vm.run{vm.repo.endWork(today.day.id);service(today.day.id,false)}},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Stop,null);Text("  Munka vége")}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onClick=onPlaces,modifier=Modifier.weight(1f)){Icon(Icons.Default.Place,null);Text("  Mai helyszínek")};OutlinedButton(onClick={onDetail(today.day.id)},modifier=Modifier.weight(1f)){Icon(Icons.Default.Edit,null);Text("  Szerkesztés")}}}}}
}
@Composable private fun HeroCard(title:String,sub:String,color:Color,button:String,icon:ImageVector,onClick:()->Unit){Card(colors=CardDefaults.cardColors(containerColor=color.copy(alpha=.1f))){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text(title,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold,color=color);Text(sub);Button(onClick=onClick,modifier=Modifier.fillMaxWidth().height(56.dp),colors=ButtonDefaults.buttonColors(containerColor=color)){Icon(icon,null);Text("  $button",style=MaterialTheme.typography.titleMedium)}}}}
@Composable private fun SummaryRow(s:hu.roadrecord.app.repository.DaySummary){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Mini("Munka",duration(s.workMillis),Green,Modifier.weight(1f));Mini("Útidő",duration(s.travelMillis),Blue,Modifier.weight(1f));Mini("Kereset",money(s.earnings),Orange,Modifier.weight(1f))}}
@Composable private fun Mini(label:String,value:String,color:Color,modifier:Modifier=Modifier){Card(modifier,colors=CardDefaults.cardColors(containerColor=color.copy(alpha=.1f))){Column(Modifier.padding(10.dp)){Text(label,style=MaterialTheme.typography.labelMedium);Text(value,fontWeight=FontWeight.Bold,color=color)}}}
@Composable private fun EventRow(e:WorkEvent,onEdit:()->Unit){val (icon,label,color)=when(e.type){EventType.WORK_START->Triple(Icons.Default.PlayArrow,"Munkakezdés",Green);EventType.TRIP_START->Triple(Icons.Default.DirectionsCar,"Útra indulás",Blue);EventType.TRIP_END->Triple(Icons.Default.Flag,"Visszaérkezés",Orange);EventType.WORK_END->Triple(Icons.Default.Stop,"Munka vége",Color.Gray)};ListItem(headlineContent={Text(label)},supportingContent={Text(time(e.timestamp))},leadingContent={Icon(icon,null,tint=color)},trailingContent={IconButton(onClick=onEdit){Icon(Icons.Default.Edit,"Szerkesztés")}})}

@Composable private fun LogScreen(vm:MainViewModel,onDay:(Long)->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("Munkanapló",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};items(days){d->val s=d.summary(settings);Card(onClick={onDay(d.day.id)}){ListItem(headlineContent={Text(d.day.date,fontWeight=FontWeight.Bold)},supportingContent={Text("${duration(s.workMillis)} munka • ${duration(s.travelMillis)} út • ${"%.1f".format(s.distanceMeters/1000)} km")},trailingContent={Text(money(s.earnings),color=Green,fontWeight=FontWeight.Bold)})}}}}
@Composable private fun EarningsScreen(vm:MainViewModel){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val periods by vm.periods.collectAsState();val now=LiveTick();val active=periods.firstOrNull{it.endDate==null};val relevant=days.filter{active==null||it.day.date>=active.startDate};val sums=relevant.map{it.summary(settings,now)};Column(Modifier.verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){Text("Eddigi kereset",style=MaterialTheme.typography.titleLarge);Text(money(sums.sumOf{it.earnings}),style=MaterialTheme.typography.displaySmall,fontWeight=FontWeight.Bold,color=Green);Text(active?.let{"${it.startDate} – jelenleg"}?:"Aktuális időszak");SummaryRow(hu.roadrecord.app.repository.DaySummary(sums.sumOf{it.workMillis},sums.sumOf{it.travelMillis},sums.sumOf{it.localMillis},sums.sumOf{it.distanceMeters},sums.sumOf{it.earnings}));Text("Óradíj: ${money(settings.hourlyRate)} / óra");Text("Ledolgozott napok: ${relevant.size}")}}
@Composable private fun StatsScreen(vm:MainViewModel){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val sums=days.map{it.summary(settings)};val work=sums.sumOf{it.workMillis};val travel=sums.sumOf{it.travelMillis};LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Statisztika",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{StatCard("Munka",listOf("Összes munkaidő" to duration(work),"Ledolgozott napok" to days.size.toString(),"Napi átlag" to duration(if(days.isEmpty())0 else work/days.size)))};item{StatCard("Utazás",listOf("Nettó útidő" to duration(travel),"Megtett kilométer" to "%.1f km".format(sums.sumOf{it.distanceMeters}/1000),"Arány" to if(work==0L)"0%" else "${travel*100/work}%"))};item{StatCard("Kereset",listOf("Összes kereset" to money(sums.sumOf{it.earnings}),"Napi átlag" to money(if(days.isEmpty())0 else sums.sumOf{it.earnings}/days.size),"Óradíj" to money(settings.hourlyRate)))}}}
@Composable private fun StatCard(title:String,rows:List<Pair<String,Any>>){Card{Column(Modifier.padding(16.dp)){Text(title,style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);rows.forEach{HorizontalDivider(Modifier.padding(vertical=7.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(it.first.toString());Text(it.second.toString(),fontWeight=FontWeight.Bold)}}}}}

@Composable private fun SettingsScreen(vm:MainViewModel,onPlaces:()->Unit){val settings by vm.settings.collectAsState();val days by vm.days.collectAsState();var rate by remember(settings.hourlyRate){mutableStateOf(settings.hourlyRate.toString())};var close by remember{mutableStateOf(LocalDate.now().toString())};val context=LocalContext.current
 LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Beállítások",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{OutlinedTextField(rate,{rate=it.filter(Char::isDigit)},label={Text("Óradíj (Ft / óra)")},modifier=Modifier.fillMaxWidth());Row(verticalAlignment=Alignment.CenterVertically){Switch(settings.includeTravelInEarnings,{vm.run{vm.repo.saveSettings(settings.copy(includeTravelInEarnings=it))}});Text("  Az útidő is beleszámít a keresetbe")};Button(onClick={vm.run{vm.repo.saveSettings(settings.copy(hourlyRate=rate.toLongOrNull()?:4500))}}){Text("Mentés")}};item{SettingsButton(Icons.Default.Place,"Helyszínek kezelése",onPlaces)};item{Card{Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Elszámolási időszak",fontWeight=FontWeight.Bold);OutlinedTextField(close,{close=it},label={Text("Lezárás dátuma (ÉÉÉÉ-HH-NN)")});OutlinedButton(onClick={vm.run{LocalDate.parse(close);vm.repo.closePeriod(close)}},modifier=Modifier.fillMaxWidth()){Text("Időszak lezárása")}}}};item{Card{Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("E-mail jelentések",fontWeight=FontWeight.Bold);OutlinedTextField(settings.reportEmail,{vm.run{vm.repo.saveSettings(settings.copy(reportEmail=it))}},label={Text("Címzett e-mail")});Text("Az automatikus küldéshez később biztonságos backend API kapcsolható. SMTP-jelszót az app nem tárol.",style=MaterialTheme.typography.bodySmall)}}};item{SettingsButton(Icons.Default.FileDownload,"CSV export"){DataExporter.csv(context,days,settings)}};item{SettingsButton(Icons.Default.DataObject,"JSON export"){DataExporter.json(context,days)}};if(hu.roadrecord.app.BuildConfig.DEBUG)item{SettingsButton(Icons.Default.Science,"Demo adatok létrehozása"){vm.run{vm.repo.seedDemo()}}}}}
@Composable private fun SettingsButton(icon:ImageVector,text:String,onClick:()->Unit){OutlinedButton(onClick=onClick,modifier=Modifier.fillMaxWidth(),contentPadding=PaddingValues(16.dp)){Icon(icon,null);Spacer(Modifier.width(10.dp));Text(text);Spacer(Modifier.weight(1f));Icon(Icons.Default.ChevronRight,null)}}

@Composable private fun PlacesScreen(vm:MainViewModel,onBack:()->Unit){val places by vm.places.collectAsState();var editing by remember{mutableStateOf<LocationPlace?>(null)};if(editing!=null){PlaceEditor(editing!!,{editing=null}){vm.run{vm.repo.savePlace(it)};editing=null};return};LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Row(verticalAlignment=Alignment.CenterVertically){IconButton(onBack){Icon(Icons.Default.ArrowBack,null)};Text("Helyszínek",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)}};item{Button(onClick={editing=LocationPlace(name="")},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Text("  Új helyszín")}};items(places){p->Card(onClick={editing=p}){ListItem(headlineContent={Text(p.name,fontWeight=FontWeight.Bold)},supportingContent={Text(p.officialAddress.ifBlank{"Nincs cím"})},leadingContent={Icon(if(p.type==PlaceType.HOME)Icons.Default.Home else Icons.Default.Person,null)},trailingContent={Icon(Icons.Default.Edit,null)})}}}}
@Composable private fun PlaceEditor(place:LocationPlace,onBack:()->Unit,onSave:(LocationPlace)->Unit){var name by remember{mutableStateOf(place.name)};var address by remember{mutableStateOf(place.officialAddress)};var lat by remember{mutableStateOf(place.latitude?.toString()?:(""))};var lng by remember{mutableStateOf(place.longitude?.toString()?:(""))};var gate by remember{mutableStateOf(place.encryptedGateCode?:"")};var note by remember{mutableStateOf(place.note)};var radius by remember{mutableStateOf(place.recognitionRadiusMeters.toString())};var type by remember{mutableStateOf(place.type)}
 Column(Modifier.verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){IconButton(onBack){Icon(Icons.Default.ArrowBack,null)};Text(if(place.id==0L)"Új helyszín" else "Helyszín szerkesztése",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};Row{FilterChip(type==PlaceType.CLIENT,{type=PlaceType.CLIENT},{Text("Ügyfél")},leadingIcon={Icon(Icons.Default.Person,null)});Spacer(Modifier.width(8.dp));FilterChip(type==PlaceType.HOME,{type=PlaceType.HOME},{Text("Home")},leadingIcon={Icon(Icons.Default.Home,null)})};Field(name,{name=it},"Név");Field(address,{address=it},"Hivatalos cím");Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(lat,{lat=it},label={Text("GPS szélesség")},modifier=Modifier.weight(1f));OutlinedTextField(lng,{lng=it},label={Text("GPS hosszúság")},modifier=Modifier.weight(1f))};Field(gate,{gate=it},"Kapukód");Field(radius,{radius=it.filter(Char::isDigit)},"Felismerési sugár (m)");Field(note,{note=it},"Megjegyzés");Text("Kulcsfotó: a készülék privát tárhelyén tárolható; a kamera/galéria engedélyét csak a funkció használatakor kéri az app.",style=MaterialTheme.typography.bodySmall);Button(onClick={if(name.isNotBlank())onSave(place.copy(type=type,name=name,officialAddress=address,latitude=lat.toDoubleOrNull(),longitude=lng.toDoubleOrNull(),encryptedGateCode=gate.ifBlank{null},note=note,recognitionRadiusMeters=radius.toIntOrNull()?:150))},modifier=Modifier.fillMaxWidth()){Text("Mentés")}}
}
@Composable private fun Field(value:String,onChange:(String)->Unit,label:String){OutlinedTextField(value,onChange,label={Text(label)},modifier=Modifier.fillMaxWidth())}

@Composable private fun DayDetail(vm:MainViewModel,id:Long,onBack:()->Unit){val day by vm.repo.observeDay(id).collectAsState(initial=null);val settings by vm.settings.collectAsState();var edit by remember{mutableStateOf<WorkEvent?>(null)};var adding by remember{mutableStateOf(false)};val d=day?:return;edit?.let{EventDialog(it,{edit=null},{vm.run{vm.repo.updateEvent(it)};edit=null},{vm.run{vm.repo.deleteEvent(it)};edit=null})};if(adding)AddEventDialog({adding=false}){type,time->vm.run{vm.repo.addEvent(id,type,time)};adding=false};LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Row(verticalAlignment=Alignment.CenterVertically){IconButton(onBack){Icon(Icons.Default.ArrowBack,null)};Column{Text(d.day.date,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Napi részletek")}}};item{SummaryRow(d.summary(settings))};items(d.events.sortedBy{it.timestamp}){EventRow(it){edit=it}};item{OutlinedButton(onClick={adding=true},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Text("  Esemény hozzáadása")}};item{OutlinedButton(onClick={},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Map,null);Text("  Térkép megnyitása (${d.trips.size} útszakasz)")}}}}
@Composable private fun EventDialog(event:WorkEvent,onDismiss:()->Unit,onSave:(WorkEvent)->Unit,onDelete:()->Unit){var value by remember{mutableStateOf(Instant.ofEpochMilli(event.timestamp).atZone(ZoneId.systemDefault()).toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")))};AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény szerkesztése")},text={OutlinedTextField(value,{value=it},label={Text("Dátum és idő")})},confirmButton={TextButton(onClick={runCatching{LocalDateTime.parse(value,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()?.let{onSave(event.copy(timestamp=it))}}){Text("Mentés")}},dismissButton={Row{TextButton(onClick=onDelete){Text("Törlés",color=Color.Red)};TextButton(onClick=onDismiss){Text("Mégse")}}})}
@Composable private fun AddEventDialog(onDismiss:()->Unit,onSave:(EventType,Long)->Unit){var type by remember{mutableStateOf(EventType.TRIP_START)};AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény hozzáadása")},text={Column{EventType.entries.forEach{Row(Modifier.clickable{type=it}.padding(6.dp),verticalAlignment=Alignment.CenterVertically){RadioButton(type==it,{type=it});Text(it.name)}}}},confirmButton={TextButton(onClick={onSave(type,System.currentTimeMillis())}){Text("Hozzáadás")}},dismissButton={TextButton(onClick=onDismiss){Text("Mégse")}})}
